import test from 'node:test'
import assert from 'node:assert/strict'
import { withStorage } from './support/profile-storage.mjs'
import { assertRecoverySelectorProfile, storedRecoveryProfile } from '../scripts/local-render/campaign-profile-recovery.mjs'

// Independent fixed fixture values, not generated by the production adapter.
const fresh = { version: 1, completed: [], nativeCampaign: {
  version: 1, flags: [4, ...Array(24).fill(0)], history: 'native-model',
} }
const before = { version: 1, completed: [1, 2], unrelated: { label: 'preserve me' } }
const returned = { ...before, nativeCampaign: {
  version: 1, flags: [5, 1, 4, ...Array(22).fill(0)], history: 'legacy-completed-only',
} }

test('recovery selector oracle permits only the exact declared fresh or legacy return transition', () => {
  const original = structuredClone(before)
  assert.deepEqual(assertRecoverySelectorProfile(undefined, fresh, []), fresh)
  assert.deepEqual(assertRecoverySelectorProfile(before, returned, [1, 2]), returned)
  assert.deepEqual(before, original, 'read-only oracle cannot normalize the fixture')
})

for (const [name, corrupt] of [
  ['missing profile', () => undefined],
  ['missing completion ledger', value => { delete value.completed; return value }],
  ['lost completion', value => { value.completed = [1]; return value }],
  ['invented completion', value => { value.completed.push(3); return value }],
  ['missing native extension', value => { delete value.nativeCampaign; return value }],
  ['incorrect availability', value => { value.nativeCampaign.flags[2] = 0; return value }],
  ['invented native completion', value => { value.nativeCampaign.flags[2] |= 1; return value }],
  ['unexpected future availability', value => { value.nativeCampaign.flags[24] = 4; return value }],
  ['incorrect history', value => { value.nativeCampaign.history = 'native-model'; return value }],
  ['lost unrelated profile metadata', value => { delete value.unrelated; return value }],
]) test(`recovery rejects persisted ${name} even when in-memory completion stays correct`, () => {
  const sessionCompleted = [1, 2]
  assert.throws(() => assertRecoverySelectorProfile(before, corrupt(structuredClone(returned)), sessionCompleted),
    /Selector must persist exactly/)
  assert.deepEqual(sessionCompleted, [1, 2])
})

test('profile observer reads the committed record in a readonly transaction and closes the database', async t => {
  const previous = Object.getOwnPropertyDescriptor(globalThis, 'indexedDB'), calls = []
  const database = {
    transaction(store, mode) {
      calls.push([store, mode])
      const transaction = { objectStore(name) {
        assert.equal(name, 'checkpoints')
        return { get(key) { assert.equal(key, 'profile'); return { result: structuredClone(returned) } } }
      } }
      queueMicrotask(() => transaction.oncomplete())
      return transaction
    },
    close() { calls.push('close') },
  }
  Object.defineProperty(globalThis, 'indexedDB', { configurable: true, value: { open(name, version) {
    assert.equal(name, 'populous-new-dawn'); assert.equal(version, 1)
    const request = { result: database }
    queueMicrotask(() => request.onsuccess())
    return request
  } } })
  t.after(() => { if (previous) Object.defineProperty(globalThis, 'indexedDB', previous); else delete globalThis.indexedDB })
  assert.deepEqual(await storedRecoveryProfile(), returned)
  assert.deepEqual(calls, [['checkpoints', 'readonly'], 'close'])
})


test('the actual store return matches the independent oracle without awarding completion or changing the world', async () => {
  for (const profile of [undefined, before]) await withStorage(profile === undefined ? {} : { profile }, async fixture => {
    const store = await fixture.freshStore(), world = store.getWorld(), initial = structuredClone(fixture.records)
    assert.equal(await store.restoreCheckpoint(), false)
    await fixture.drain()
    assert.deepEqual(fixture.records, initial, 'Restore is still strictly no-write')
    assert.deepEqual(fixture.writes, [])
    const completed = store.getCompletedMissions()
    store.enterCampaignSelector()
    await fixture.drain()
    assert.equal(store.getWorld(), world)
    assert.deepEqual(store.getCompletedMissions(), completed)
    assertRecoverySelectorProfile(profile, fixture.records.get('profile'), completed)
  })
})
